// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor.code.length == 0);
        vm.assume(actor != address(c));
        amount = bound(amount, 1, 1 ether);

        // actor deposits amount, then withdraws it all
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        vm.prank(actor);
        c.withdraw(amount);

        // A second withdraw of the same amount must fail: balance is 0 now.
        bool ok;
        vm.prank(actor);
        try c.withdraw(amount) { ok = true; } catch { ok = false; }

        assertTrue(!ok);
    }
}
